package com.nthexperience.desktop;

import android.content.*;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import java.util.*;

final class XpCardGame extends XpToolPanel {
    XpCards game;private final boolean free;private final LinearLayout table;private int selected=-1,selectedIndex=-1;private String hint="";
    XpCardGame(Context c,DesktopStore store,Host host,boolean free){super(c,store,host,free?"@freecell":"@solitaire");this.free=free;command("New Game",()->Aero.dialog(c).setTitle("New deal?").setMessage("Replace this saved game with a shuffled deal?").setPositiveButton("Deal",(d,w)->{game=new XpCards(free,new Random().nextLong());selected=-1;render();}).setNegativeButton("Cancel",null).show());command("Undo",()->{game.undo();selected=-1;render();});command("Hint",()->{hint=game.hint();say(hint);});if(!free)command("Draw 1 / 3",()->{game.draw=game.draw==1?3:1;render();});command("Help",()->Aero.dialog(c).setTitle(free?"FreeCell":"Solitaire").setMessage("Tap a visible card, then tap a destination pile. Tap the selected top card again to move it to its foundation. Dragging also moves a valid sequence. Build tableau columns downward in alternating colors and foundations from Ace to King in each suit. "+(free?"Free cells hold one card; empty columns and cells determine how many cards can move together.":"Empty columns take Kings. Tap the stock to draw, then recycle it when empty. Draw one or three is selectable.")+" Undo reverses moves. Your deal is saved locally.").setPositiveButton("OK",null).show());
        try{game=XpCards.restore(c.getSharedPreferences("xp_games",0).getString(free?"freecell":"solitaire",""));if(game.freecell!=free)throw new IllegalArgumentException();}catch(Exception e){game=new XpCards(free,new Random().nextLong());}table=Aero.column(c);table.setBackgroundColor(0xff008000);table.setPadding(dp(4),dp(5),dp(4),dp(5));content.addView(table,new FrameLayout.LayoutParams(-1,-1));render();}
    private void save(){try{getContext().getSharedPreferences("xp_games",0).edit().putString(free?"freecell":"solitaire",game.state().toString()).apply();}catch(Exception ignored){}}
    private void render(){table.removeAllViews();LinearLayout top=new LinearLayout(getContext());if(free){for(int i=0;i<4;i++)slot(top,XpCards.CELL+i,-1,"Free cell "+(i+1));}else{Card stock=new Card(getContext(),game.stock.isEmpty()?-5:-2,false,selected==XpCards.STOCK);stock.emptyLabel="↻";stock.setContentDescription("Draw stock: "+game.stock.size()+" cards");stock.setOnClickListener(v->{game.drawStock();selected=-1;render();});top.addView(stock,new LayoutParams(0,dp(68),1));slot(top,XpCards.WASTE,game.waste.size()-1,"Waste");Space gap=new Space(getContext());top.addView(gap,new LayoutParams(0,1,1));}
        for(int i=0;i<4;i++)slot(top,XpCards.FOUNDATION+i,game.foundations.get(i).size()-1,"Foundation "+new String[]{"spades","hearts","clubs","diamonds"}[i]);table.addView(top,new LayoutParams(-1,dp(72)));
        LinearLayout columns=new LinearLayout(getContext());for(int col=0;col<game.tableau.size();col++){
            int pile=col;FrameLayout stack=new FrameLayout(getContext());stack.setContentDescription("Column "+(col+1));stack.setOnClickListener(v->choose(pile,-1));drop(stack,pile);List<Integer> cards=game.tableau.get(col);int offset=dp(19);for(int at=0;at<cards.size();at++){int index=at,card=cards.get(at);Card view=new Card(getContext(),card,game.face[card],selected==col&&selectedIndex==at);view.setContentDescription(game.face[card]?"Column "+(col+1)+": "+XpCards.name(card):"Covered card");view.setOnClickListener(v->choose(pile,index));view.setOnLongClickListener(v->{if(!game.face[card])return false;selected=pile;selectedIndex=index;v.startDragAndDrop(android.content.ClipData.newPlainText("Card",XpCards.name(card)),new View.DragShadowBuilder(v),XpCardGame.this,0);return true;});FrameLayout.LayoutParams bounds=new FrameLayout.LayoutParams(-1,dp(68));bounds.topMargin=at*offset;stack.addView(view,bounds);}
            int height=Math.max(dp(92),cards.size()*offset+dp(68));LinearLayout.LayoutParams bounds=new LayoutParams(0,height,1);bounds.setMargins(dp(2),dp(5),dp(2),0);columns.addView(stack,bounds);
        }
        ScrollView scroll=new ScrollView(getContext());scroll.addView(columns);table.addView(scroll,new LayoutParams(-1,0,1));save();say(game.won()?"You won! Deal a new game to play again.":selected>=0?"Selected card — tap a legal destination":"Moves: "+game.moves+(free?" • FreeCell":" • Draw "+game.draw)+" • tap a card, then a pile");
    }
    private void slot(LinearLayout row,int pile,int index,String title){List<Integer> cards=game.pile(pile);int top=XpCards.last(cards);Card view=new Card(getContext(),top,true,selected==pile);view.emptyLabel=pile>=XpCards.CELL&&pile<XpCards.CELL+4?"•":pile==XpCards.WASTE?"":new String[]{"A♠","A♥","A♣","A♦"}[pile-XpCards.FOUNDATION];view.setContentDescription(title+(top<0?", empty":": "+XpCards.name(top)));view.setOnClickListener(v->choose(pile,cards.size()-1));drop(view,pile);LinearLayout.LayoutParams bounds=new LayoutParams(0,dp(68),1);bounds.setMargins(dp(2),0,dp(2),0);row.addView(view,bounds);}
    private void choose(int pile,int index){if(selected>=0){if(selected==pile&&selectedIndex==index&&game.autoFoundation(pile,index)){selected=-1;render();return;}if(game.move(selected,selectedIndex,pile)){selected=-1;render();return;}}List<Integer> cards=game.pile(pile);if(index>=0&&index<cards.size()&&game.face[cards.get(index)]){selected=pile;selectedIndex=index;render();}else{selected=-1;render();}}
    private void drop(View view,int pile){view.setOnDragListener((v,e)->{if(e.getLocalState()!=XpCardGame.this)return false;if(e.getAction()==DragEvent.ACTION_DROP){boolean moved=game.move(selected,selectedIndex,pile);selected=-1;render();if(!moved)say("That move is not legal");}return true;});}
    @Override void active(boolean value){if(!value)save();}
    @Override void close(){if(closed)return;save();closed=true;}
    private final class Card extends View {final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);String emptyLabel="";final int card;final boolean face,selected;Card(Context c,int card,boolean face,boolean selected){super(c);this.card=card;this.face=face;this.selected=selected;setFocusable(true);}
        @Override protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setStyle(Paint.Style.FILL);p.setColor(card<0&&card!=-2?0xff006800:face&&card>=0?Color.WHITE:0xff17448f);c.drawRoundRect(1,1,w-1,h-1,dp(3),dp(3),p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(selected?dp(3):dp(1));p.setColor(selected?0xffffff00:0xffdfdfdf);c.drawRoundRect(1,1,w-1,h-1,dp(3),dp(3),p);p.setStyle(Paint.Style.FILL);
            if(card>=0&&face){p.setTypeface(Aero.strong(getContext()));p.setTextSize(dp(13));p.setColor(XpCards.red(card)?0xffc00000:Color.BLACK);p.setTextAlign(Paint.Align.LEFT);c.drawText(XpCards.name(card),dp(3),dp(16),p);p.setTextSize(dp(25));p.setTextAlign(Paint.Align.CENTER);c.drawText(new String[]{"♠","♥","♣","♦"}[XpCards.suit(card)],w/2,h*.75f,p);}else if(card==-2||card>=0){p.setColor(0xff8eafff);p.setStrokeWidth(dp(1));for(float x=4;x<w-4;x+=dp(7))c.drawLine(x,dp(5),x,h-dp(5),p);for(float y=5;y<h-4;y+=dp(7))c.drawLine(dp(4),y,w-dp(4),y,p);}else{p.setTextAlign(Paint.Align.CENTER);p.setTextSize(dp(18));p.setColor(0xffb8d2b8);c.drawText(emptyLabel,w/2,h*.62f,p);}}
    }
}
